//! Parses the samples of `conformance/` with the format definitions next to
//! them, which are written in the Kaitai Struct language, and compares the
//! result with what the reference Kaitai Struct compiler's parser produced
//! (`conformance/expected/`, generated by `conformance/generate.js`).
//!
//! Both sides are brought to one canonical form first: keys without case and
//! underscores (the JavaScript runtime renames `file_size` to `fileSize`),
//! enums as their numbers, byte sequences as hex, no `null`s, and none of
//! doe's `$` metadata.

use std::path::{Path, PathBuf};

use doe::{OutputFormat, parse_file};
use serde_json::{Map, Value as Json};

fn conformance_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../conformance")
}

fn normalize_key(key: &str) -> String {
    key.chars()
        .filter(|c| *c != '_')
        .flat_map(char::to_lowercase)
        .collect()
}

/// The canonical form of doe's JSON output.
fn canonical(value: &Json) -> Json {
    match value {
        Json::Array(items) => Json::Array(items.iter().map(canonical).collect()),
        Json::Object(map) => match map.get("$type").and_then(Json::as_str) {
            Some("bytes") => map.get("hex").cloned().unwrap_or(Json::Null),
            Some("enum") => map.get("value").cloned().unwrap_or(Json::Null),
            _ => Json::Object(
                map.iter()
                    // `$type` and the like; and the unnamed fields (`_unnamed0`),
                    // which the reference leaves out of its output.
                    .filter(|(key, _)| !key.starts_with('$') && !key.starts_with('_'))
                    .map(|(key, v)| (normalize_key(key), canonical(v)))
                    .collect(),
            ),
        },
        Json::Number(n) => match n.as_f64() {
            // The reference prints 1.0 as 1.
            Some(x) if n.is_f64() && x.fract() == 0.0 && x.abs() < 9e15 =>
            {
                #[expect(
                    clippy::cast_possible_truncation,
                    reason = "the value is integral and small"
                )]
                Json::from(x as i64)
            }
            _ => value.clone(),
        },
        other => other.clone(),
    }
}

/// Numbers only, as in [`canonical`], for output that is already canonical.
fn canonical_numbers(value: &Json) -> Json {
    match value {
        Json::Array(items) => Json::Array(items.iter().map(canonical_numbers).collect()),
        Json::Object(map) => Json::Object(
            map.iter()
                .map(|(key, v)| (key.clone(), canonical_numbers(v)))
                .collect(),
        ),
        Json::Number(_) => canonical(value),
        other => other.clone(),
    }
}

/// Remove the keys whose value is `null`: a field that was not read is absent
/// in doe and `undefined` in the reference.
fn without_nulls(value: &Json) -> Json {
    match value {
        Json::Array(items) => Json::Array(items.iter().map(without_nulls).collect()),
        Json::Object(map) => Json::Object(
            map.iter()
                .filter(|(_, v)| !v.is_null())
                .map(|(key, v)| (key.clone(), without_nulls(v)))
                .collect::<Map<_, _>>(),
        ),
        other => other.clone(),
    }
}

fn samples(format: &str) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(conformance_dir().join("samples").join(format))
        .unwrap_or_else(|e| panic!("no samples for {format}: {e}"))
        .filter_map(|entry| {
            let name = entry.ok()?.file_name().into_string().ok()?;
            name.strip_suffix(".bin").map(str::to_owned)
        })
        .collect();
    names.sort();
    names
}

/// The definitions of the Kaitai Struct gallery, a git submodule.
///
/// A clone made without `--recurse-submodules` has the directory empty: it is
/// checked out here, once, so that `cargo test` works in any clone. When that
/// cannot be done (not a git checkout, no network), the tests that need the
/// definitions say so.
fn gallery_dir() -> PathBuf {
    static CHECKED_OUT: std::sync::Once = std::sync::Once::new();
    let dir = conformance_dir().join("kaitai_struct_formats");
    CHECKED_OUT.call_once(|| {
        if dir.join("README.md").exists() {
            return;
        }
        let root = conformance_dir();
        // A failure shows as the missing definitions, which the tests report.
        drop(
            std::process::Command::new("git")
                .args([
                    "submodule",
                    "update",
                    "--init",
                    "--",
                    "kaitai_struct_formats",
                ])
                .current_dir(&root)
                .env("GIT_TERMINAL_PROMPT", "0")
                .output(),
        );
    });
    dir
}

/// The definition of `format`: a file of `formats/`, or, for `gallery/<path>`,
/// `<path>.ksy` in the gallery.
fn definition(format: &str) -> PathBuf {
    match format.strip_prefix("gallery/") {
        Some(path) => {
            let ksy = gallery_dir().join(format!("{path}.ksy"));
            assert!(
                ksy.exists(),
                "{} does not exist; the gallery is a git submodule: run `git submodule update --init`",
                ksy.display()
            );
            ksy
        }
        None => conformance_dir()
            .join("formats")
            .join(format!("{format}.ksy")),
    }
}

/// Parse every sample of `format` and report all the ways it differs.
fn check(format: &str) {
    let dir = conformance_dir();
    let ksy = definition(format);
    let names = samples(format);
    assert!(!names.is_empty(), "{format} has no samples");
    let mut failures = Vec::new();
    for name in &names {
        let sample = dir.join("samples").join(format).join(format!("{name}.bin"));
        let expected_path = dir
            .join("expected")
            .join(format)
            .join(format!("{name}.json"));
        let expected: Json = serde_json::from_str(
            &std::fs::read_to_string(&expected_path)
                .unwrap_or_else(|e| panic!("{}: {e}", expected_path.display())),
        )
        .expect("the expected output is JSON");
        // The gallery definitions import each other from the root of the gallery.
        let include: Vec<PathBuf> = if format.starts_with("gallery/") {
            vec![gallery_dir()]
        } else {
            Vec::new()
        };
        let actual = match parse_file(
            &sample,
            ksy.to_str().expect("the path is UTF-8"),
            &include,
            Some(Path::new("/nonexistent/config.toml")),
            OutputFormat::Json,
        ) {
            Ok(text) => without_nulls(&canonical(
                &serde_json::from_str::<Json>(&text).expect("doe's output is JSON"),
            )),
            Err(e) => {
                failures.push(format!("{format}/{name}: doe failed: {e:#?}"));
                continue;
            }
        };
        let expected = without_nulls(&canonical_numbers(&expected));
        if actual != expected {
            failures.push(format!(
                "{format}/{name}: output differs\n--- reference\n{}\n--- doe\n{}",
                serde_json::to_string_pretty(&expected).unwrap_or_default(),
                serde_json::to_string_pretty(&actual).unwrap_or_default(),
            ));
        }
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n\n"));
}

macro_rules! formats {
    ($($name:ident),* $(,)?) => {
        $(
            #[test]
            fn $name() {
                check(stringify!($name));
            }
        )*

        /// Every format in `conformance/formats/` has a test above, and the
        /// other way round.
        #[test]
        fn every_format_is_tested() {
            let mut on_disk: Vec<String> = std::fs::read_dir(conformance_dir().join("formats"))
                .expect("conformance/formats exists")
                .filter_map(|entry| {
                    let name = entry.ok()?.file_name().into_string().ok()?;
                    name.strip_suffix(".ksy").map(str::to_owned)
                })
                .collect();
            on_disk.sort();
            let mut tested = vec![$(stringify!($name).to_owned()),*];
            tested.sort();
            assert_eq!(on_disk, tested);
        }
    };
}

